
const User = require('../models/User');
const sendEmail = require('../utils/sendEmail');
const admin = require('../config/firebaseAdmin');

const crypto = require('crypto');
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');

const FRONTEND_BASE_URL = (
  process.env.FRONTEND_URL || 'https://habitra-abdu2.vercel.app'
  ).replace(/\/+$/, '');

  const DEFAULT_TIMEZONE = 'Africa/Addis_Ababa';

  const generateToken = (id) => {
    if (!process.env.JWT_SECRET) {
        throw new Error('JWT_SECRET is not configured.');
          }

            return jwt.sign({ id }, process.env.JWT_SECRET, {
                expiresIn: '30d'
                  });
                  };

                  const normalizeEmail = (email) =>
                    String(email || '').trim().toLowerCase();

                    const buildFrontendUrl = (path, params = {}) => {
                      const url = new URL(path, `${FRONTEND_BASE_URL}/`);

                        Object.entries(params).forEach(([key, value]) => {
                            url.searchParams.set(key, String(value));
                              });

                                return url.toString();
                                };

                                const createError = (message, statusCode) => {
                                  const error = new Error(message);
                                    error.statusCode = statusCode;
                                      return error;
                                      };

                                      // ==========================================
                                      // FIREBASE VERIFICATION EMAIL
                                      // ==========================================

                                      const sendFirebaseVerificationEmail = async (email) => {
                                        const verifyUrl = await admin.auth().generateEmailVerificationLink(
                                            email,
                                                {
                                                      url: buildFrontendUrl('/verify-email', { email }),
                                                            handleCodeInApp: false
                                                                }
                                                                  );

                                                                    await sendEmail({
                                                                        email,
                                                                            subject: 'Verify Your HABITRA Account',
                                                                                message: `
                                                                                Welcome to HABITRA!

                                                                                Please verify your email using this secure link:

                                                                                ${verifyUrl}

                                                                                If you did not create this account, ignore this email.
                                                                                `,
                                                                                    html: `
                                                                                          <div style="font-family:Arial,sans-serif;max-width:600px;margin:auto;">
                                                                                                  <h2>Welcome to HABITRA!</h2>
                                                                                                          <p>Thank you for creating your account.</p>
                                                                                                                  <p>Please verify your email address to activate your account.</p>
                                                                                                                          <a href="${verifyUrl}"
                                                                                                                                    style="display:inline-block;padding:12px 22px;background:#174C38;color:white;text-decoration:none;border-radius:6px;">
                                                                                                                                              Verify Email
                                                                                                                                                      </a>
                                                                                                                                                              <p>If you did not create this account, ignore this email.</p>
                                                                                                                                                                    </div>
                                                                                                                                                                        `
                                                                                                                                                                          });
                                                                                                                                                                          };

                                                                                                                                                                          // ==========================================
                                                                                                                                                                          // REGISTER
                                                                                                                                                                          // ==========================================

                                                                                                                                                                          const register = async (body) => {
                                                                                                                                                                            const { name, password, timezone } = body;
                                                                                                                                                                              const email = normalizeEmail(body.email);

                                                                                                                                                                                if (!name || !email || !password) {
                                                                                                                                                                                    throw createError('Name, email, and password are required.', 400);
                                                                                                                                                                                      }

                                                                                                                                                                                        if (password.length < 8) {
                                                                                                                                                                                            throw createError('Password must contain at least 8 characters.', 400);
                                                                                                                                                                                              }

                                                                                                                                                                                                if (String(name).trim().length < 2) {
                                                                                                                                                                                                    throw createError('Name must contain at least 2 characters.', 400);
                                                                                                                                                                                                      }

                                                                                                                                                                                                        const existingUser = await User.findOne({ email });

                                                                                                                                                                                                          if (existingUser) {
                                                                                                                                                                                                              throw createError('An account with this email already exists.', 409);
                                                                                                                                                                                                                }

                                                                                                                                                                                                                  // Firebase user must have been created by the frontend first.
                                                                                                                                                                                                                    let firebaseUser;

                                                                                                                                                                                                                      try {
                                                                                                                                                                                                                          firebaseUser = await admin.auth().getUserByEmail(email);
                                                                                                                                                                                                                            } catch (error) {
                                                                                                                                                                                                                                if (error.code === 'auth/user-not-found') {
                                                                                                                                                                                                                                      throw createError(
                                                                                                                                                                                                                                              'Firebase account was not created. Please try registration again.',
                                                                                                                                                                                                                                                      400
                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                    throw error;
                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                        if (firebaseUser.emailVerified) {
                                                                                                                                                                                                                                                                            throw createError(
                                                                                                                                                                                                                                                                                  'This Firebase email is already verified. Please contact support if you cannot access your account.',
                                                                                                                                                                                                                                                                                        409
                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                const passwordHash = await bcrypt.hash(password, 12);

                                                                                                                                                                                                                                                                                                  const user = new User({
                                                                                                                                                                                                                                                                                                      name: String(name).trim(),
                                                                                                                                                                                                                                                                                                          email,
                                                                                                                                                                                                                                                                                                              passwordHash,
                                                                                                                                                                                                                                                                                                                  timezone: timezone || DEFAULT_TIMEZONE,
                                                                                                                                                                                                                                                                                                                      isVerified: false
                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                          await user.save();

                                                                                                                                                                                                                                                                                                                            try {
                                                                                                                                                                                                                                                                                                                                await sendFirebaseVerificationEmail(email);
                                                                                                                                                                                                                                                                                                                                  } catch (error) {
                                                                                                                                                                                                                                                                                                                                      // Keep the account so the user can request another email.
                                                                                                                                                                                                                                                                                                                                          console.error('Firebase verification email failed:', error.message);

                                                                                                                                                                                                                                                                                                                                              throw createError(
                                                                                                                                                                                                                                                                                                                                                    'Your account was created, but the verification email could not be sent. Please use resend verification.',
                                                                                                                                                                                                                                                                                                                                                          503
                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                  // Do not issue a JWT before email verification.
                                                                                                                                                                                                                                                                                                                                                                    return {
                                                                                                                                                                                                                                                                                                                                                                        _id: user._id,
                                                                                                                                                                                                                                                                                                                                                                            name: user.name,
                                                                                                                                                                                                                                                                                                                                                                                email: user.email,
                                                                                                                                                                                                                                                                                                                                                                                    isVerified: false,
                                                                                                                                                                                                                                                                                                                                                                                        message: 'Account created. Please check your email to verify your account.'
                                                                                                                                                                                                                                                                                                                                                                                          };
                                                                                                                                                                                                                                                                                                                                                                                          };

                                                                                                                                                                                                                                                                                                                                                                                          // ==========================================
                                                                                                                                                                                                                                                                                                                                                                                          // FIREBASE EMAIL VERIFICATION
                                                                                                                                                                                                                                                                                                                                                                                          // ==========================================

                                                                                                                                                                                                                                                                                                                                                                                          const verifyFirebaseEmail = async (email) => {
                                                                                                                                                                                                                                                                                                                                                                                            const normalizedEmail = normalizeEmail(email);

                                                                                                                                                                                                                                                                                                                                                                                              if (!normalizedEmail) {
                                                                                                                                                                                                                                                                                                                                                                                                  throw createError('Email is required.', 400);
                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                      let firebaseUser;

                                                                                                                                                                                                                                                                                                                                                                                                        try {
                                                                                                                                                                                                                                                                                                                                                                                                            firebaseUser = await admin.auth().getUserByEmail(normalizedEmail);
                                                                                                                                                                                                                                                                                                                                                                                                              } catch (error) {
                                                                                                                                                                                                                                                                                                                                                                                                                  if (error.code === 'auth/user-not-found') {
                                                                                                                                                                                                                                                                                                                                                                                                                        throw createError('Firebase account not found.', 404);
                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                throw error;
                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                    // Never trust an email address supplied by the frontend alone.
                                                                                                                                                                                                                                                                                                                                                                                                                                      if (!firebaseUser.emailVerified) {
                                                                                                                                                                                                                                                                                                                                                                                                                                          throw createError(
                                                                                                                                                                                                                                                                                                                                                                                                                                                'Firebase has not confirmed this email yet. Please open the verification link in your email.',
                                                                                                                                                                                                                                                                                                                                                                                                                                                      403
                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                              const user = await User.findOne({ email: normalizedEmail });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!user) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    throw createError('HABITRA account not found.', 404);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        user.isVerified = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          user.verificationToken = undefined;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            user.verificationTokenExpires = undefined;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                              await user.save();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    message: 'Email successfully verified! Your HABITRA account is now active.'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // ==========================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // LEGACY EMAIL VERIFICATION
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // ==========================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const verifyEmail = async (token, email) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!token || !email) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            throw createError('Verification token and email are required.', 400);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const hashedToken = crypto
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .createHash('sha256')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .update(token)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .digest('hex');

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const user = await User.findOne({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  email: normalizeEmail(email),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      verificationToken: hashedToken,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          verificationTokenExpires: { $gt: new Date() }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (!user) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  throw createError('Invalid or expired verification token.', 400);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      user.isVerified = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        user.verificationToken = undefined;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          user.verificationTokenExpires = undefined;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            await user.save();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  message: 'Email successfully verified!'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // ==========================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // RESEND VERIFICATION
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // ==========================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const resendVerificationEmail = async (email) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const normalizedEmail = normalizeEmail(email);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!normalizedEmail) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            throw createError('Email is required.', 400);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const genericResponse = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    message: 'If an unverified account exists, a verification email will be sent.'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const user = await User.findOne({ email: normalizedEmail });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (!user || user.isVerified) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return genericResponse;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const firebaseUser = await admin.auth().getUserByEmail(normalizedEmail);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (firebaseUser.emailVerified) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                user.isVerified = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      await user.save();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return genericResponse;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    await sendFirebaseVerificationEmail(normalizedEmail);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      } catch (error) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          console.error('Resend verification failed:', error.message);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (error.statusCode) throw error;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  throw createError(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'Unable to send verification email. Please try again later.',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              503
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return genericResponse;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // ==========================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // FORGOT PASSWORD
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // ==========================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const forgotPassword = async (email) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const normalizedEmail = normalizeEmail(email);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (!normalizedEmail) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              throw createError('Email is required.', 400);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const user = await User.findOne({ email: normalizedEmail });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const genericResponse = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        message: 'If an account exists with that email, a password reset link will be sent.'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!user) return genericResponse;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const resetToken = user.getResetPasswordToken();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                await user.save();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const resetUrl = buildFrontendUrl('/reset-password', {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      token: resetToken
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              await sendEmail({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    email: user.email,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          subject: 'HABITRA Password Reset',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                message: `Reset your HABITRA password using this link:\n\n${resetUrl}\n\nThis link expires in 10 minutes.`,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      html: `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div style="font-family:Arial,sans-serif;max-width:600px;margin:auto;">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <h2>Reset Your Password</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <p>You requested a password reset.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <a href="${resetUrl}" style="display:inline-block;padding:12px 22px;background:#174C38;color:white;text-decoration:none;border-radius:6px;">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Reset Password
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </a>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <p>This link expires in 10 minutes.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                } catch (error) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    console.error('Password reset email failed:', error.message);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        throw createError('Unable to send password reset email.', 503);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return genericResponse;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // ==========================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // RESET PASSWORD
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // ==========================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const resetPassword = async (token, newPassword) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (!token || !newPassword) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  throw createError('Reset token and new password are required.', 400);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (newPassword.length < 8) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          throw createError('Password must contain at least 8 characters.', 400);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const hashedToken = crypto
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  .createHash('sha256')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      .update(token)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          .digest('hex');

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const user = await User.findOne({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                resetPasswordToken: hashedToken,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    resetPasswordExpires: { $gt: new Date() }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!user) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            throw createError('Invalid or expired password reset token.', 400);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                user.passwordHash = await bcrypt.hash(newPassword, 12);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  user.resetPasswordToken = undefined;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    user.resetPasswordExpires = undefined;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      await user.save();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return { message: 'Password reset successfully!' };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // ==========================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // LOGIN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // ==========================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const login = async (body) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const email = normalizeEmail(body.email);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const { password } = body;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (!email || !password) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  throw createError('Email and password are required.', 400);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const user = await User.findOne({ email });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!user || !(await bcrypt.compare(password, user.passwordHash))) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            throw createError('Invalid email or password.', 401);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Check Firebase as well as MongoDB.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (!user.isVerified) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const firebaseUser = await admin.auth().getUserByEmail(email);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (firebaseUser.emailVerified) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          user.isVerified = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  await user.save();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } catch (error) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (error.code !== 'auth/user-not-found') throw error;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (!user.isVerified) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              throw createError(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'Please verify your email before signing in. Check your inbox or request a new verification email.',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          403
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      _id: user._id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          name: user.name,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              email: user.email,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  isVerified: user.isVerified,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      token: generateToken(user._id)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        module.exports = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          register,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            verifyEmail,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              verifyFirebaseEmail,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                resendVerificationEmail,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  forgotPassword,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    resetPassword,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      login
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      